struct entity_id
{
  char data[8];
};

struct po
{
  float data[16];

  po &operator=(const po &other)
  {
    for (int i = 0; i < 16; ++i)
      data[i] = other.data[i];
    return *this;
  }
};

class bone
{
public:
  bone();
};

enum entity_flavor_t
{
  ENTITY_ENTITY = 1
};

class entity : public bone
{
  char padding[352];
  po *last_po;

  void _construct(
    const entity_id &, entity_flavor_t, short, unsigned int,
    const po &);

public:
  entity(const entity_id &, unsigned int, const po &);
};

extern const po identity_po;

entity::entity(
  const entity_id &_id, unsigned int _flags,
  const po &last_po_init_val)
  : bone()
{
  _construct(_id, ENTITY_ENTITY, -1, _flags, identity_po);
  last_po = new po;
  *last_po = last_po_init_val;
}
